function StoreChargeDialog:RefreshSelf(params)
    self._hideToggle = checkTable(params).hideToggle
    
    local dataKey = StoreUtils.GetDataKey(StoreConstants.OpenIds.Diamond)
    self.chargeData = StoreUtils.GetStoreComp().AllStores[dataKey]
    self:RefreshView()
end

function StoreChargeDialog:BtnChargeRewardsClickHandler()
    UIModule.OpenDialog({ id = Constants.UITypeIds.CumulativeRechargeDialog, parameters = { showType = 1 }}, {})
end

function StoreChargeDialog:BtnServiceClickHandler()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo

    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    ---@type UserComponent
    local userComp = entity:GetComp(ECSComponentType.Constants.UserComponent)
    local concatTable = {
        phone = "",
        app_name = "猫之城",
        username = "",
        role_name = playerDojo.playerName,
        uid = playerDojo.playerId,
        channel = tostring(GameUtils.GetChannelId()),
        server = "1",
        open_id = userComp.openId or ""
    }
    local contactList = {}
    local UnityWebRequest = CS.UnityEngine.Networking.UnityWebRequest
    for key, value in pairs(concatTable) do
        contactList[#contactList+1] =  table.concat({key, "=",  UnityWebRequest.EscapeURL(tostring(value))})
    end
    -- 获取到链接的字符串
    local contactStr = table.concat(contactList,"&")
    GameUtils.SetCommunityClick(self.BtnService.gameObject , 5, nil,true , contactStr)
end

function StoreChargeDialog:RefreshLeftData()
    if #self.chargeData > 1 then
        local dojo = self.chargeData[1]
        --printInfo("dojo.goodId" .. table.dump(dojo))
        --printInfo("dojo.goodId" .. tostring(dojo.goodsId))
        local goodsVo = goodsConfMgr:GetGoodsVoById(dojo.goodsId)
        self.ChargeName.text = goodsVo.name
        self.Description.text = goodsVo.desc
    end
end

function StoreChargeDialog:RefreshView()
    if self._hideToggle then
        KTool.SetActive(self.BtnTopUp, false)
    else
        KTool.SetActive(self.BtnTopUp, GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id165))
    end
    
    GameUtils.ReloadData(self.ScrollView, #self.chargeData)
    self:RefreshRedPoint()
end

function StoreChargeDialog:RefreshRedPoint()
    if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id165) then
        local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)
        local state = redPointCom:GetServerRedPointData(Constants.RedPointConst.ShopAccumulativePay)
        KTool.SetActive(self.redPoint, state == 0)
    else
        KTool.SetActive(self.redPoint, false)
    end
end

function StoreChargeDialog:OnGetItemByIndex(listView, index, row, column)
    --printInfo("index" .. index)
    if index < 0 then
        return nil
    end
    local pos = index + 1
    local cell = listView:NewListViewItem(PrefabName)
    ---@type Engine.Modules.LuaBehaviour
    local chargeCellNode = GetLuaBehaviour(cell.gameObject, chargeItemPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        --是否需要cell的init的逻辑
        chargeCellNode:Init()
    end
    local dojo = self.chargeData[pos]
    if not KTool.IsNull(dojo) then
        chargeCellNode.Env:RefreshState(dojo, pos)
    end
    return cell
end

function StoreChargeDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local comp = StoreUtils.GetStoreComp()
                comp:InitialStore(response.data)
                self:RefreshSelf()
            end
        end)
    end
end

function StoreChargeDialog:OnDestroy()
    if self.isShowBg and (self.dontDispose ~= nil and not self.dontDispose) then
        StoreShared:DisposeAll()
    end
    Events.RemoveListener(Constants.EventNames.StoreAccumulativePayRefresh, self.EventAccumulativePayRefresh)
    Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.EventSdkEvent)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return StoreChargeDialog